<?php

declare(strict_types=1);

namespace App\Support\Crypto;

/**
 * Time-based one-time passwords (RFC 6238 over RFC 4226), ported from
 * apps/api/src/auth/totp.ts and verified against codes generated by that implementation.
 *
 * SHA-1, 6 digits and a 30-second step are not choices: they are what Google Authenticator, Authy,
 * 1Password and every other authenticator assume when a URI omits them. The security of a TOTP
 * comes from the shared secret and the short window, not from the hash.
 *
 * Implemented on PHP's own hash/random functions rather than a package: a TOTP is thirty lines of
 * HMAC and a counter, and a dependency in the authentication path is one more thing to audit.
 */
final class Totp
{
    public const DIGITS = 6;
    public const PERIOD_SECONDS = 30;

    /**
     * How many steps either side of "now" are accepted. One step (+/-30 s) tolerates a phone clock
     * that drifts or a code typed as it expires, and costs an attacker only a factor of three.
     */
    public const WINDOW_STEPS = 1;

    /** 160 bits, the size RFC 4226 recommends for an HMAC-SHA1 key. */
    private const SECRET_BYTES = 20;

    private const BASE32_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

    /** A new random secret, base32-encoded for an authenticator app. */
    public static function generateSecret(): string
    {
        return self::base32Encode(random_bytes(self::SECRET_BYTES));
    }

    /** The time step a moment falls in. */
    public static function timeStep(\DateTimeInterface $at): int
    {
        return intdiv($at->getTimestamp(), self::PERIOD_SECONDS);
    }

    /** The code for one time step. */
    public static function code(string $secret, int $timeStep): string
    {
        $digest = hash_hmac('sha1', pack('J', $timeStep), self::base32Decode($secret), true);

        // RFC 4226 section 5.4 dynamic truncation.
        $offset = ord($digest[strlen($digest) - 1]) & 0x0f;
        $binary = ((ord($digest[$offset]) & 0x7f) << 24)
            | (ord($digest[$offset + 1]) << 16)
            | (ord($digest[$offset + 2]) << 8)
            | ord($digest[$offset + 3]);

        return str_pad((string) ($binary % (10 ** self::DIGITS)), self::DIGITS, '0', STR_PAD_LEFT);
    }

    /**
     * Checks a code against the accepted window.
     *
     * @param int|null $usedStep the last time step this credential already spent, so a code cannot
     *   be replayed. A code from that step or earlier is refused even though the arithmetic matches.
     * @return int|null the time step the code belongs to, or null if it matches none. The caller
     *   stores the returned step as `usedStep`.
     */
    public static function verify(string $secret, string $code, \DateTimeInterface $at, ?int $usedStep): ?int
    {
        $candidate = preg_replace('/\s+/', '', $code) ?? '';

        if (preg_match('/^\d{'.self::DIGITS.'}$/', $candidate) !== 1) {
            return null;
        }

        $current = self::timeStep($at);

        for ($offset = -self::WINDOW_STEPS; $offset <= self::WINDOW_STEPS; $offset++) {
            $step = $current + $offset;

            if ($usedStep !== null && $step <= $usedStep) {
                continue;
            }

            // hash_equals: a timing difference here would leak how much of a code was correct.
            if (hash_equals(self::code($secret, $step), $candidate)) {
                return $step;
            }
        }

        return null;
    }

    private static function base32Encode(string $raw): string
    {
        $bits = 0;
        $value = 0;
        $out = '';

        for ($i = 0, $len = strlen($raw); $i < $len; $i++) {
            $value = ($value << 8) | ord($raw[$i]);
            $bits += 8;

            while ($bits >= 5) {
                $out .= self::BASE32_ALPHABET[($value >> ($bits - 5)) & 31];
                $bits -= 5;
            }
        }

        if ($bits > 0) {
            $out .= self::BASE32_ALPHABET[($value << (5 - $bits)) & 31];
        }

        return $out;
    }

    private static function base32Decode(string $secret): string
    {
        $bits = 0;
        $value = 0;
        $out = '';

        foreach (str_split(strtoupper(rtrim($secret, '='))) as $char) {
            $index = strpos(self::BASE32_ALPHABET, $char);

            if ($index === false) {
                throw new \InvalidArgumentException('Secret is not valid base32');
            }

            $value = ($value << 5) | $index;
            $bits += 5;

            if ($bits >= 8) {
                $out .= chr(($value >> ($bits - 8)) & 0xff);
                $bits -= 8;
            }
        }

        return $out;
    }
}
